                    out.s5 = await st();
                    // ④ 选 A、⌘+B，拖 B 那一行到数字「2」上
                    await J('(function () { tr.nodes([]); selectedNode = null; refreshLayers(); return true; })()');
                    const rowsNow = (await st()).rows;
                    const iA = rowsNow.indexOf('A'), iB = rowsNow.indexOf('B');
                    await clickAt(await rowPt(iA));
                    await clickAt(await rowPt(iB), ['meta']);
                    out.s6 = await st();
                    const orderBefore = await J(`layerNodes().map((n) => n.getAttr('cmTag'))`);
                    const pB = iB >= 0 ? await rowPt(iB) : { x: 0, y: 0 };
                    const n2 = await J(`(function () { const el = document.querySelectorAll('#layerFrames .layer-frame-no')[1]; const b = el.getBoundingClientRect(); return { x: Math.round(b.left + b.width / 2), y: Math.round(b.top + b.height / 2), gk: el.getAttribute('data-frame-gk') }; })()`);
                    win.webContents.sendInputEvent({ type: 'mouseMove', x: pB.x, y: pB.y }); await W8(30);
                    win.webContents.sendInputEvent({ type: 'mouseDown', x: pB.x, y: pB.y, button: 'left', clickCount: 1 }); await W8(30);
                    for (let k = 1; k <= 14; k++) { win.webContents.sendInputEvent({ type: 'mouseMove', x: Math.round(pB.x + (n2.x - pB.x) * k / 14), y: Math.round(pB.y + (n2.y - pB.y) * k / 14), modifiers: ['leftButtonDown'] }); await W8(25); }
                    await W8(80);
                    out.hover = await J(`(function () { const el = document.querySelectorAll('#layerFrames .layer-frame-no')[1]; return { drop: el.classList.contains('drop'), ring: !!(frameSelRing && frameSelRing.visible()), ringGk: selectedFrameGk, tab: layerTabGk }; })()`);
                    win.webContents.sendInputEvent({ type: 'mouseUp', x: n2.x, y: n2.y, button: 'left', clickCount: 1 }); await W8(300);
                    out.s7 = await st();
                    out.drop = await J(`(function () { return { sel: tr.nodes().map((n) => ({ t: n.getAttr('cmTag'), gk: layerFrameGkOf(n) })), orderOld: layerNodes().filter((n) => tr.nodes().indexOf(n) < 0).map((n) => n.getAttr('cmTag')),
                        dropCls: document.querySelectorAll('#layerFrames .layer-frame-no.drop').length, ring: !!(frameSelRing && frameSelRing.visible()) }; })()`);
                    out.orderBefore = orderBefore; out.n2gk = n2.gk;
                    if (out.s7.n > out.s6.n) { await J('(function () { undo(); return true; })()'); await W8(200); }
                    out.s8 = await st();
                    // ⑤ 拖到自己那块框的数字「1」上 = 原地复制
                    await J('(function () { layerTabGk = null; tr.nodes([]); selectedNode = null; refreshLayers(); return true; })()');
                    const rowsN = (await st()).rows; const iC = rowsN.indexOf('C');
                    await clickAt(await rowPt(iC));
                    const pC = iC >= 0 ? await rowPt(iC) : { x: 0, y: 0 };
                    const n1 = await J(`(function () { const el = document.querySelectorAll('#layerFrames .layer-frame-no')[0]; const b = el.getBoundingClientRect(); return { x: Math.round(b.left + b.width / 2), y: Math.round(b.top + b.height / 2), gk: el.getAttribute('data-frame-gk') }; })()`);
                    win.webContents.sendInputEvent({ type: 'mouseMove', x: pC.x, y: pC.y }); await W8(30);
                    win.webContents.sendInputEvent({ type: 'mouseDown', x: pC.x, y: pC.y, button: 'left', clickCount: 1 }); await W8(30);
                    for (let k = 1; k <= 14; k++) { win.webContents.sendInputEvent({ type: 'mouseMove', x: Math.round(pC.x + (n1.x - pC.x) * k / 14), y: Math.round(pC.y + (n1.y - pC.y) * k / 14), modifiers: ['leftButtonDown'] }); await W8(25); }
                    if (process.env.CM_LAYERDROP_SHOT) { await W8(150); await fs.writeFile(process.env.CM_LAYERDROP_SHOT, (await win.webContents.capturePage()).toPNG()); }
