                    const insideOk = (s) => !!s.横框 && s.横框[0] >= -0.5
                        && s.横框[0] + s.横框[2] <= s.canvas[0] + 0.5 && s.横框[1] + s.横框[3] <= s.canvas[1] + 0.5;
