                                    if (!box || !n) return null;
                                    const c = contentRect(box), r = rectOfNode(n);
                                    const ow = Math.min(r.x + r.width, c.x + c.width) - Math.max(r.x, c.x);
                                    const oh = Math.min(r.y + r.height, c.y + c.height) - Math.max(r.y, c.y);
