                    const cc = await MCP.handleRpc({ jsonrpc: '2.0', id: 1, method: 'tools/call', params: { name: 'create_cover', arguments: {
                        title: '人挡字测试', platforms: ['douyin'], image_paths: ['C:/tmp/cm_zoom.png'], subject_front: true, replace_canvas: true, auto_export: false,
                        custom_style: { subject_outline_color: '#FFFFFF', subject_outline_width: 5 } } } });
                    let ccv = null; try { ccv = JSON.parse(cc.result.content.find((c) => c.type === 'text').text); } catch (e) { /* 空 */ }
