                        const s = await win.webContents.executeJavaScript('window.__cmZP.snap()');
                        // 每一档都要成立：① 自己那块框里**还有图**（没消失）② 旁边那块框里**没有图**（一图一框没破）
                        //                  ③ 裁剪范围 = **自己那块框**
                        const okStep = isImgPx(s.自框中心) && isEmpty(s.横框中心) && near4(s.图clip, s.竖框, 1.5);
                        zpSteps.push({ zoom: f, ok: okStep, 自框中心: s.自框中心, 横框中心: s.横框中心, 图clip: s.图clip, 竖框: s.竖框 });
                        zoomProbeOk = zoomProbeOk && okStep;
