                        const small = await lfWindow(() => { win.unmaximize(); win.setSize(lfSmall[0] || 1024, lfSmall[1] || 700); },
                                                     big && big.canvas);                              // 用户报的那一步 = 「缩到最小」
                        const back = await lfWindow(() => win.maximize(), small && small.canvas);     // 再回最大：必须复原（不能「缩了就回不去」）
                        win.unmaximize(); win.setSize(1280, 800);
                        await new Promise((r) => setTimeout(r, 400));

                        const maxAbs = (s) => (s && s.dev ? Math.max.apply(null, s.dev.map(function (v) { return Math.abs(v); })) : 9);
                        const canvasChanged = !!(big && small && (big.canvas[0] !== small.canvas[0] || big.canvas[1] !== small.canvas[1]));
                        const dBig = maxAbs(big), dSmall = maxAbs(small), dBack = maxAbs(back);
                        // 判据①：**框里露白**（用户肉眼那条）—— 最大 / 最小 / 回最大 三态都不许超过 2px
                        const bandOf = (s) => (s && s.band ? s.band.max : 999);
