                                    const r34 = get(window.__cmFK.gk.v), r43 = get(window.__cmFK.gk.h43), r169 = get(window.__cmFK.gk.h169);
                                    const R = function (r) { return r ? [Math.round(r.x), Math.round(r.y), Math.round(r.width), Math.round(r.height)] : null; };
                                    const B = function (r) { return r ? [Math.round(r.x), Math.round(r.y), Math.round(r.width), Math.round(r.height)] : null; };
                                    let ov = 0;
