                                        const ix = Math.max(0, Math.min(r43.x + r43.width, r169.x + r169.width) - Math.max(r43.x, r169.x));
                                        const iy = Math.max(0, Math.min(r43.y + r43.height, r169.y + r169.height) - Math.max(r43.y, r169.y));
                                        ov = (ix * iy) / Math.min(r43.width * r43.height, r169.width * r169.height);
