                        const back = await fkWindow(() => { win.setContentSize(before0.view[0], before0.view[1]); }, big && big.canvas);
                        console.log('[cover-maker] selftest framekeep 放大后(用户截图2):', JSON.stringify(big));
                        console.log('[cover-maker] selftest framekeep 缩回原尺寸:', JSON.stringify(back));
                        const overlapOf = (s) => s.横版框重叠比例;
                        const belowOf = (s) => s['16:9在4:3下面'] === true;
                        const setupOk = overlapOf(before0) <= 0.02 && belowOf(before0);               // ①
                        const bigOk = overlapOf(big) <= 0.02 && belowOf(big);                         // ②
                        // ③ 位移按**统一比例 S** 走：dx、dy 的放大倍数都该 = S 的倍数（S = min(W/740, H/427)）
                        const sc = (s) => Math.min(s.canvas[0] / 740, s.canvas[1] / 427);
