                    const bMoved = bFrame.filter((v) => !(v[0] === 0 && v[1] === 0));
                    const bHeld = bFrame.filter((v) => (v[0] === 0 && v[1] === 0));
                    const bOk = near(bImg, 35, -25) && B0.选中.选中图 === false && B0.solo === null
                        && bMoved.length === 1 && near(bMoved[0], 35, -25) && bHeld.length === 1;
                    // ③ §0.93：**双击**才放行 → 只动图；且双击没建文字、没弹输入框、确实点亮了 solo
                    const eMoved = eFrame.filter((v) => !(v[0] === 0 && v[1] === 0));
