                    const endA = await scr(`(function () { const c = ${cellsExpr}[0]; return { x: c.x + c.width / 2, y: c.y + c.height * 0.75 }; })()`);
                    await dbl(startA);
                    out.soloA = await js("!!soloImage && soloImage.getAttr('cmTag')");
                    await drag(startA, endA);
                    const a1 = await info('P1'), b1 = await info('P2');
                    out.A = { a0, a1, b0, b1, dy: endA.y - startA.y };
                    // B：拖到第 2 格
                    const startB = await scr(`(function () { const c = ${cellsExpr}[0]; return { x: c.x + c.width / 2, y: c.y + c.height * 0.3 }; })()`);
                    const endB = await scr(`(function () { const c = ${cellsExpr}[1]; return { x: c.x + c.width / 2, y: c.y + c.height * 0.6 }; })()`);
                    await js('(function () { exitSoloMove(); tr.nodes([]); selectedNode = null; return true; })()');
                    await dbl(startB);
                    await drag(startB, endB);
                    const a2 = await info('P1'), b2 = await info('P2');
                    out.B = { a2, b2 };
                    // C：不分块的横框 → 用竖框：先取消分块、清掉照片，放一张进竖框（不分块），双击后往右拖
                    await js(`(async function () { exitSoloMove(); tr.nodes([]); selectedNode = null; mainLayer.find('Image').forEach((n) => n.destroy()); window.__cmSplit.set('left|0.7500', null);
                        const V = guideFrameRectsByGk['left|0.7500']; await pasteImagePaths([${JSON.stringify(imgArg)}], { x: V.x + V.width / 2, y: V.y + V.height / 2 }); mainLayer.find('Image').slice(-1)[0].setAttr('cmTag', 'PC');
                        exitSoloMove(); tr.nodes([]); selectedNode = null; refreshLayers(); return true; })()`);
                    const startC = await scr("(function () { const V = guideFrameRectsByGk['left|0.7500']; return { x: V.x + V.width * 0.1, y: V.y + V.height / 2 }; })()");
                    const endC = await scr("(function () { const V = guideFrameRectsByGk['left|0.7500']; return { x: V.x + V.width * 0.92, y: V.y + V.height / 2 }; })()");
