                    await js(`(function () { window.__cmOldSplitAssign = false; mainLayer.find('Image').forEach((n) => n.destroy()); Object.keys(window.__cmSplit.splits).forEach((k) => delete window.__cmSplit.splits[k]);
                        activePlatforms.length = 0; mainPlatform = null; resetFrameOffsets(); syncPlatformMenu(); drawPlatformFrame(); refreshLayers(); window.__cmHistoryReset(); return true; })()`);
                    const vis = (r) => ['R', 'G', 'B'].filter((t) => r[t] >= 0.6).length;
