                    const back = rows[5], back2 = rows[7];
                    const s3 = [back, back2].every((r) => r.key === 'h3' && vis(r) === 3 && r.cell.R === 0 && r.cell.G === 1 && r.cell.B === 2);
                    splitSwitchOk = s1 && s2 && s3;
