                    await js("(function () { if (window.__bPh) window.__bPh.destroy(); window.__bPh = null; tr.nodes([]); selectedNode = null; mainLayer.draw(); refreshLayers(); const t = document.querySelector('#color-panel .color-tab[data-tab=\"rgb\"]'); if (t) t.click(); window.__cmHistoryReset(); return true; })()");
                    const q1 = b1.n === 24 && b1.filled === 24;
