                    const wait = (ms) => new Promise((r) => setTimeout(r, ms));
                    const key = async (k) => { win.webContents.sendInputEvent({ type: 'keyDown', keyCode: k }); win.webContents.sendInputEvent({ type: 'keyUp', keyCode: k }); await wait(120); };
                    const dbl = async (p) => {
                        win.webContents.sendInputEvent({ type: 'mouseMove', x: p.x, y: p.y });
                        win.webContents.sendInputEvent({ type: 'mouseDown', x: p.x, y: p.y, button: 'left', clickCount: 1 });
                        win.webContents.sendInputEvent({ type: 'mouseUp', x: p.x, y: p.y, button: 'left', clickCount: 1 });
                        await wait(60);
                        win.webContents.sendInputEvent({ type: 'mouseDown', x: p.x, y: p.y, button: 'left', clickCount: 2 });
                        win.webContents.sendInputEvent({ type: 'mouseUp', x: p.x, y: p.y, button: 'left', clickCount: 2 });
                        await wait(250);
                    };
                    const at = (sel) => js(`(function () { const el = document.querySelector('#layerList .layer-row[data-kind="T"] ${sel}'); if (!el) return null;
                        el.scrollIntoView({ block: 'end' }); const r = el.getBoundingClientRect(); const x = Math.round(r.left + Math.min(20, r.width / 2)), y = Math.round(r.top + r.height / 2);
                        const hit = document.elementFromPoint(x, y); return { x: x, y: y, ok: !!(hit && hit.closest && hit.closest('${sel}') === el) }; })()`);
