                    await js("(function () { tr.nodes([]); selectedNode = null; window.__rT.destroy(); mainLayer.find('.贴纸').forEach((n) => n.destroy()); mainLayer.draw(); refreshLayers(); window.__cmHistoryReset(); return true; })()");
                    const k1 = !!p0 && p0.ok && r1.input && r1.focused && r1.val === r0.name && r1.sel;
                    const k2 = r2.name === '封面标题' && r2.attr === '封面标题' && !r2.input && r2.steps === r0.steps + 1;
                    const k3 = r3.undo === r0.name && r3.redo === '封面标题';
