                    tmpWin.destroy();
                    await new Promise((r) => setTimeout(r, 400));
                    const after = liveWin(tmpWin);
                    const reallyDestroyed = tmpWin.isDestroyed();
                    const mainAlive = !!liveWin();
                    let sendThrew = false;
                    try { sendCommand('undo'); } catch (e) { sendThrew = true; }
