                        const stackOf = (side, ratio) => computeFrames()
                            .filter(f => f.side === side && Math.abs(f.ratio - ratio) < 1e-9)
                            .sort((a, b) => b.stackNo - a.stackNo)                  // 从下到上
                            .map(f => f.key + '#' + f.sizeIndex + '|第' + f.stackNo + '/' + f.stackSize + '层');
