                        //   ⚠ 本段在 executeJavaScript 的模板字符串里 —— 注释里**一个字都不能出现反引号**（踩过三次）
                        const drawnTop = () => { const l = guideLayer.find('.平台框'); return l.length ? l[l.length - 1].getAttr('frameKey') : null; };
                        const rows = () => Array.prototype.map.call(document.querySelectorAll('#frameList .layer-row'), (r) => ({
                            key: r.getAttribute('data-frame'),
                            name: r.querySelector('.layer-name').textContent,
                            idx: r.querySelector('.layer-idx').textContent,
                            isMain: !!r.querySelector('.main-tag'),
                            ops: r.querySelectorAll('.layer-op').length        // §0.60：换层按钮已撤 → 应为 0
                        }));
                        const rect = (key, si) => { const f = computeFrames().find(x => x.key === key && x.sizeIndex === si); return f ? f.rect : null; };
                        const borderPt = (key, si) => { const r0 = rect(key, si); return { x: Math.round(r0.x + 1), y: Math.round(r0.y + r0.height / 2) }; };
                        const hitAt = (p) => { const h = stage.getIntersection(p); return h ? (h.getAttr('frameKey') || h.name() || h.getClassName()) : 'none'; };
                        const status = () => document.getElementById('statusText').textContent;

                        // §0.60：单选口径 —— 走真实入口选「抖音」（它自己就有 竖 3:4 + 横 4:3 两档）
                        activePlatforms.length = 0; mainPlatform = null; drawPlatformFrame(); syncPlatformMenu();
                        togglePlatform('douyin');
