                //   负对照 --nodefaultbyuse（window.__cmNoDefaultByUse）→ 永远系统字体 → ②③④ 必挂。
                let defaultFontOk = true;
                if (process.argv.includes('--defaultfont')) {
                    const d = await win.webContents.executeJavaScript(`(async function () {
                        await loadFonts(false);
                        window.__cmNoDefaultByUse = ${process.argv.includes('--nodefaultbyuse') ? 'true' : 'false'};
                        const KEY = 'cm_fontUseOrder';
                        const saved = localStorage.getItem(KEY);
                        const reset = function () { localStorage.removeItem(KEY); FONT_USE.loaded = false; FONT_USE.map = {}; FONT_USE.next = 1; };
                        reset();
                        const sys = systemDefaultFont();
                        const d0 = defaultFont();
                        const pool = ['KaiTi', 'SimSun', 'FangSong', 'STKaiti', 'Songti SC', 'Kaiti SC'].filter(function (f) { return fontAvailable(f) && f !== sys; });
                        const others = FONTS.list.filter(function (f) { return f !== sys && pool.indexOf(f) < 0; });
                        const A = pool[0] || others[0], B = pool[1] || others[1];
                        bumpFontUse(A); bumpFontUse(A); bumpFontUse(B);
                        const d1 = defaultFont();
                        const n = makeTextNode(100, 100);
                        const newFont = n.fontFamily(); n.destroy();
                        for (let i = 0; i < 5; i++) bumpFontUse('本机不存在的字体XYZ');
                        const d2 = defaultFont();
                        bumpFontUse(B); bumpFontUse(B);
                        const d3 = defaultFont();
                        if (saved === null) localStorage.removeItem(KEY); else localStorage.setItem(KEY, saved);
                        FONT_USE.loaded = false;
                        window.__cmNoDefaultByUse = false;
                        return { sys: sys, A: A, B: B, d0: d0, d1: d1, newFont: newFont, d2: d2, d3: d3 };
                    })()`);
                    const df1 = d.d0 === d.sys;
                    const df2 = !!d.A && d.d1 === d.A && d.newFont === d.A;
                    const df3 = d.d2 === d.A;
                    const df4 = !!d.B && d.d3 === d.B;
                    defaultFontOk = df1 && df2 && df3 && df4;
                    console.log('[cover-maker] selftest defaultfont 判据:', JSON.stringify({
                        实测: d, '①没记录=系统字体': df1, '②最常用=默认且新建文字用它': df2, '③本机没有的不当默认': df3, '④次数超过后跟着换': df4,
                        ok: defaultFontOk }));
                }

                // 场景：--textfx §4.3（用户 2026-10-13「字体和阴影加一个透明度，阴影再加一个大小，参考 ps」）—— **像素级**
                //   夹具：一个绿色「国」字（160px）、红色阴影、角度 0°（正下方）、距离 40% —— 全走右栏真控件（input 事件）。
                //   在 mainLayer.toCanvas()（透明底，走真实绘制）上数像素：「绿」= 字本身，「红」= 阴影。
                //   ① 字透明度 30 → 字的平均 alpha ≈ 30%，而**阴影浓度不变**（≈ 100 时的阴影）；
                //   ② 字透明度 0 → 一个绿像素都没有，阴影还在（面积不比 100 时小 —— 原来被字盖住的那截也露出来）；
                //   ③ 阴影透明度 40 → 阴影平均 alpha ≈ 默认 80 时的一半；
                //   ④ 阴影大小 0 → 20：阴影晕开的范围变大（红色区域外框变高、半透明边缘像素变多）；
                //   ⑤ 面板回显：选别的再选回来，三个值原样回来；⑥ 撤销一次 → 回到上一档。
                //   ⑦ 描边：字透明 0 时外描边 / 内描边那一圈的像素数和不透明时一样（外描边压在字里那半不许露出来）。
                //   负对照 --fillwhole（window.__cmFillOpacityWhole = 退回整段一起淡）→ ① 必挂（阴影跟着淡）。
                let textFxOk = true;
                if (process.argv.includes('--textfx')) {
                    const x = await win.webContents.executeJavaScript(`(function () {
                        mainLayer.getChildren().slice().forEach(function (c) { if (c !== tr) c.destroy(); });
                        tr.nodes([]); selectedNode = null;
                        window.__cmFillOpacityWhole = ${process.argv.includes('--fillwhole') ? 'true' : 'false'};
                        window.__cmHistoryReset();
                        const n = makeTextNode(80, 120);
                        n.text('国'); n.fontSize(160); n.fill('#00ff00');
                        mainLayer.add(n); mainLayer.draw();
                        const other = makeTextNode(400, 60); other.text('别的'); mainLayer.add(other);
                        selectNode(n);
                        const set = function (id, v) { const el = document.getElementById(id); el.value = String(v); el.dispatchEvent(new Event('input', { bubbles: true })); };
                        set('tpShadow', '#ff0000');
                        set('tpShadowA', 0);
                        set('tpShadowD', 40);
                        set('tpShadowO', 80);
                        set('tpShadowS', 6);
                        other.visible(false);
                        // 数像素：绿 = 字（g 明显最大），红 = 阴影（r 明显最大）
                        const measure = function () {
                            mainLayer.draw();
                            tr.visible(false);
                            const c = mainLayer.toCanvas({ pixelRatio: 1 });
                            tr.visible(true);
                            const d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data;
                            let gN = 0, gA = 0, rN = 0, rA = 0, rSoft = 0, rTop = 1e9, rBot = -1, bN = 0;
                            for (let i = 0, px = 0; i < d.length; i += 4, px++) {
                                const r = d[i], g = d[i + 1], b = d[i + 2], a = d[i + 3];
                                if (a < 8) continue;
                                if (g > r + 40 && g > b + 40) { gN++; gA += a; }
                                else if (b > r + 40 && b > g + 40 && a > 128) { bN++; }
                                else if (r > g + 40 && r > b + 40) {
                                    rN++; rA += a; if (a < 160) rSoft++;
                                    const y = Math.floor(px / c.width); if (y < rTop) rTop = y; if (y > rBot) rBot = y;
                                }
                            }
                            return { gN: gN, gA: gN ? Math.round(gA / gN) : 0, rN: rN, rA: rN ? Math.round(rA / rN) : 0, rSoft: rSoft, rH: rBot >= 0 ? rBot - rTop : 0, bN: bN };
                        };
                        const base = measure();
                        set('tpOpacity', 30);  const f30 = measure();
                        set('tpOpacity', 0);   const f0 = measure();
                        set('tpOpacity', 100);
                        set('tpShadowO', 40);  const s40 = measure();
                        set('tpShadowO', 80);
                        set('tpShadowS', 0);   const z0 = measure();
                        set('tpShadowS', 20);  const z20 = measure();
                        // ⑦ 描边（蓝）：字透明 0 时描边那圈不变 —— 外描边不许把压在字里的那一半露出来，内描边不许跟着字一起没了
                        set('tpShadowD', 0);
                        set('tpStroke', '#0000ff'); set('tpStrokeW', 8);
                        const so100 = measure(); set('tpOpacity', 0); const so0 = measure(); set('tpOpacity', 100);
                        const innerBox = document.getElementById('tpStrokeInner'); innerBox.checked = true; innerBox.dispatchEvent(new Event('change', { bubbles: true }));
                        const si100 = measure(); set('tpOpacity', 0); const si0 = measure(); set('tpOpacity', 100);
                        const outerBox = document.getElementById('tpStrokeOuter'); outerBox.checked = true; outerBox.dispatchEvent(new Event('change', { bubbles: true }));
                        set('tpStrokeW', 0); set('tpShadowD', 40);
                        // ⑤ 回显：先把三个值设成可辨认的一档，选别的再选回来
                        set('tpOpacity', 55); set('tpShadowO', 65); set('tpShadowS', 12);
                        hist.lastKey = null;
                        other.visible(true); selectNode(other); selectNode(n);
                        const shown = { op: document.getElementById('tpOpacity').value, so: document.getElementById('tpShadowO').value, ss: document.getElementById('tpShadowS').value,
                                        opR: document.getElementById('tpOpacityR').value, soR: document.getElementById('tpShadowOR').value, ssR: document.getElementById('tpShadowSR').value };
                        // ⑥ 撤销：最后一步是「阴影大小 12」→ 撤一次回到 20
                        window.__appCommand('undo');
                        const n2 = mainLayer.find('Text').filter(function (t) { return t.text() === '国'; })[0];
                        const afterUndo = n2 ? { blurPct: n2.getAttr('shadowBlurPct'), fo: n2.getAttr('fillOpacity'), so: n2.shadowOpacity() } : null;
                        mainLayer.getChildren().slice().forEach(function (c) { if (c !== tr) c.destroy(); });
                        tr.nodes([]); selectedNode = null; window.__cmFillOpacityWhole = false; window.__cmHistoryReset(); mainLayer.draw();
                        return { base: base, f30: f30, f0: f0, s40: s40, z0: z0, z20: z20, so100: so100, so0: so0, si100: si100, si0: si0, shown: shown, afterUndo: afterUndo };
                    })()`);
                    const near = (a, b, tol) => Math.abs(a - b) <= tol;
                    const fx1 = x.base.gN > 500 && x.base.rN > 500
                        && near(x.f30.gA / x.base.gA, 0.3, 0.08)                            // 字淡到 ~30%
                        && near(x.f30.rA, x.base.rA, 12);                                   // 阴影浓度不变
                    const fx2 = x.f0.gN === 0 && x.f0.rN >= x.base.rN * 0.95 && near(x.f0.rA, x.base.rA, 12);
                    const fx3 = near(x.s40.rA / x.base.rA, 0.5, 0.1);
                    const fx4 = x.z20.rH > x.z0.rH + 10 && x.z20.rSoft > x.z0.rSoft * 2;
                    const fx5 = x.shown.op === '55' && x.shown.so === '65' && x.shown.ss === '12'
                        && x.shown.opR === '55' && x.shown.soR === '65' && x.shown.ssR === '12';
                    const fx6 = !!x.afterUndo && Number(x.afterUndo.blurPct) === 20 && Number(x.afterUndo.fo) === 0.55 && near(x.afterUndo.so, 0.65, 0.001);
                    const fx7 = x.so100.bN > 300 && near(x.so0.bN / x.so100.bN, 1, 0.12) && x.so0.gN === 0
                        && x.si100.bN > 300 && near(x.si0.bN / x.si100.bN, 1, 0.12) && x.si0.gN === 0;
                    textFxOk = fx1 && fx2 && fx3 && fx4 && fx5 && fx6 && fx7;
                    console.log('[cover-maker] selftest textfx 判据:', JSON.stringify({
                        实测: x, '①字透明30·阴影浓度不变': fx1, '②字透明0·只剩阴影': fx2, '③阴影透明度40≈默认一半': fx3,
                        '④阴影大小变大范围变大': fx4, '⑤面板回显': fx5, '⑥撤销一步': fx6, '⑦字透明0时外/内描边那圈不变': fx7, ok: textFxOk }));
                }

                // 场景：--eraser §4.4（用户 2026-10-13「加一个橡皮擦功能，参考 ps，在哪个图层就只能擦除哪个图层」）—— 像素级 + 真鼠标
                //   夹具：一张红色「照片」（Konva.Image name 素材，300×200）+ 压在上面的绿色「国」字（160px）。没开平台（照片不裁）。
                //   ① 右键点在字上 → 菜单里有「橡皮擦」→ 点它 = 进入橡皮擦、选中的就是这段字、画布上盖了操作层；
                //   ② 真鼠标横着拖一笔穿过字 → 字的绿像素变少、笔迹中心露出**下面的红照片**（照片没被擦 = 只擦选中层）；
                //   ③ 改选照片（= 图层列表点它）在字下方拖一笔 → 那里变透明，字的绿像素一个没少；
