                    await jsE(`(function () { mainLayer.getChildren().slice().forEach(function (c) { if (c !== tr) c.destroy(); }); tr.nodes([]); selectedNode = null; window.__cmNoErase = false; window.__cmHistoryReset(); mainLayer.draw(); return true; })()`);
                    const isRed = (c) => c[0] > 200 && c[1] < 60 && c[3] > 200;
                    const isGreen = (c) => c[1] > 200 && c[0] < 80;
                    const er1 = e1.items.indexOf('橡皮擦') >= 0 && e1.on && e1.selIsText && e1.ov && e1.bar;
                    const er2 = isGreen(px0.mid) && px2.strokes === 1 && px2.imgStrokes === 0 && px2.green < px0.green * 0.92 && isRed(px2.mid);
                    const er3 = px3.imgStrokes === 1 && px3.at[3] < 10 && px3.green === px2.green;
                    const er4 = px4.at[3] > 90 && px4.at[3] < 165 && px4.at[0] > 200;
                    const er5 = px5.hard.clear > 300 && px5.soft.soft > px5.hard.soft * 2;
                    const er6 = n5 === 4 && n6 === 3;
                    const er7 = px7.strokesAfterEdit === 1 && isRed(px7.midMoved) && Math.abs(px7.greenMoved - px7.green0) < px7.green0 * 0.05;
